<!-- About > Licenses: the third-party notices generated by scripts/gen-licenses.mjs
     (`npm run licenses`) into static/licenses.json, as in Farba. A searchable list grouped by
     kind; a row expands to the project's address and licence text. -->
<script lang="ts">
  import { invoke } from "@tauri-apps/api/core";
  import { ChevronRight, Search } from "@lucide/svelte";
  import { t } from "../i18n.svelte";
  import Modal from "./Modal.svelte";

  interface Pkg {
    kind: "bundled" | "rust" | "js";
    name: string;
    version: string;
    license: string;
    repository: string;
    note?: string;
    texts: string[];
  }
  interface Data {
    generated: string;
    packages: Pkg[];
    texts: Record<string, string>;
  }

  interface Props {
    onclose: () => void;
  }
  let { onclose }: Props = $props();

  let data = $state<Data | null>(null);
  let error = $state<string | null>(null);
  let query = $state("");
  let openKey = $state<string | null>(null);

  const GROUPS: { kind: Pkg["kind"]; label: string }[] = $derived([
    { kind: "bundled", label: t("lic_bundled") },
    { kind: "rust", label: t("lic_rust") },
    { kind: "js", label: t("lic_js") },
  ]);

  const filtered = $derived.by(() => {
    const q = query.trim().toLowerCase();
    const list = data?.packages ?? [];
    return q ? list.filter((p) => p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q)) : list;
  });
  const summary = $derived.by(() => {
    const counts = new Map<string, number>();
    for (const p of data?.packages ?? []) counts.set(p.license, (counts.get(p.license) ?? 0) + 1);
    return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6);
  });

  fetch("/licenses.json")
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
    .then((d: Data) => (data = d))
    .catch((e) => (error = String(e)));

  const key = (p: Pkg) => `${p.kind}:${p.name}@${p.version}`;
</script>

<Modal title={t("licenses_h")} wide oncancel={onclose}>
  <p class="intro">
    {t("licenses_intro")}
    {#if data}· {t("licenses_count", data.packages.length)}{/if}
  </p>
  {#if data}
    <label class="search">
      <Search size={14} />
      <input type="text" placeholder={t("licenses_search")} bind:value={query} spellcheck="false" />
    </label>
    <div class="chips">
      {#each summary as [lic, n] (lic)}
        <button class="chip" class:on={query === lic} onclick={() => (query = query === lic ? "" : lic)}>{lic} · {n}</button>
      {/each}
    </div>
    <div class="list">
      {#each GROUPS as g (g.kind)}
        {@const items = filtered.filter((p) => p.kind === g.kind)}
        {#if items.length}
          <h3>{g.label} <span class="dim">({items.length})</span></h3>
          {#each items as p (key(p))}
            {@const k = key(p)}
            <div class="item" class:open={openKey === k}>
              <button class="row" aria-expanded={openKey === k} onclick={() => (openKey = openKey === k ? null : k)}>
                <ChevronRight size={14} class="chev" />
                <span class="name ellipsis">{p.name}{#if p.version}<span class="ver">{p.version}</span>{/if}</span>
                <span class="lic ellipsis" title={p.license}>{p.license}</span>
              </button>
              {#if openKey === k}
                <div class="body">
                  {#if p.note}<p class="note">{p.note}</p>{/if}
                  <button class="link" onclick={() => void invoke("open_url", { url: p.repository })}>{p.repository}</button>
                  {#each p.texts as id (id)}
                    <pre>{data.texts[id]}</pre>
                  {/each}
                </div>
              {/if}
            </div>
          {/each}
        {/if}
      {/each}
    </div>
  {:else if error}
    <p class="dim">{error}</p>
  {:else}
    <p class="dim">…</p>
  {/if}
  {#snippet footer()}
    <button class="btn primary" onclick={onclose}>{t("close")}</button>
  {/snippet}
</Modal>

<style>
